private async Task ListenAsync(CancellationToken ct)
{
    while (!ct.IsCancellationRequested && _listener != null && _listener.IsListening)
    {
        try
        {
            var context = await _listener.GetContextAsync();
            _ = ProcessRequestAsync(context, ct);
        }
        catch (HttpListenerException) when (ct.IsCancellationRequested || _listener == null || !_listener.IsListening)
        {
            break;
        }
        catch (Exception ex)
        {
            System.Diagnostics.Debug.WriteLine($"[ScadaDebugBridge] Error accepting request: {ex.Message}");
        }
    }
}

